LAYER_NAMES = {1:"Mathematics",2:"Learning theory",3:"Data",4:"Architecture",5:"Training",6:"Framework",
 7:"Kernels",8:"Hardware",9:"Inference/serving",10:"Systems around model",11:"Evaluation",12:"Security & integrity",13:"Deployment & org"}

prs = json.load(open("data/prs.json"))
for p in prs:
    key = f"{p['repo']}#{p['number']}"
    c = C.get(key)
    if not c:
        print("MISSING", key); continue
    p.update(c); p["layer_name"] = LAYER_NAMES[c["layer"]]
    p["risk"] = round(((c["exposure"]+c["ease"])/2) * ((c["gain"]+c["blast"])/2), 1)
    p["is_feature"] = c["threat"].startswith("(Feature")
json.dump(dict(prs=prs, layer_names=LAYER_NAMES), open("data/classified.json","w"), indent=1)
print("classified", sum(1 for p in prs if "layer" in p), "| missing", sum(1 for p in prs if "layer" not in p))
print("by layer:", dict(Counter(p["layer_name"] for p in prs if "layer_name" in p)))
print("features:", sum(1 for p in prs if p.get("is_feature")), "| bug fixes:", sum(1 for p in prs if "layer" in p and not p.get("is_feature")))
